import json, glob, os, datetime

S = "/private/tmp/claude-501/-Users-burakemre-Code-lobu/4226e7a7-3646-49f8-ac53-c326d3a23430/scratchpad"
REQ = {"typecheck", "format-lint", "migrations", "unit", "integration", "frontend", "pi-review"}

seen = {}
for f in sorted(glob.glob(os.path.join(S, "p[123].json"))):
    for p in json.load(open(f)):
        seen[p["number"]] = p
prs = sorted(seen.values(), key=lambda p: -p["number"])


def parse(t):
    return datetime.datetime.strptime(t, "%Y-%m-%dT%H:%M:%SZ")


clean, dirty = 0, []
ttm = []
for p in prs:
    st = {}
    for c in p.get("statusCheckRollup") or []:
        n = c.get("name") or c.get("context")
        if not n:
            continue
        s = c.get("conclusion") or c.get("state")
        if st.get(n) in ("FAILURE", "TIMED_OUT", "CANCELLED"):
            continue
        st[n] = s
    bad = [n for n, s in st.items() if s in ("FAILURE", "TIMED_OUT", "CANCELLED") and n in REQ]
    miss = REQ - set(st)
    if bad or miss:
        dirty.append(p["number"])
    else:
        clean += 1

n = len(prs)
print(f"=== GATE INTEGRITY over {n} merged PRs (#{min(seen)}..#{max(seen)}) ===")
print(f"  merged with ALL 7 required checks green : {clean}  ({100*clean//n}%)")
print(f"  merged past a failing/absent required   : {len(dirty)}  ({100*len(dirty)//n}%)")

print("\n=== TIME FROM PR CREATION TO MERGE ===")
for p in prs:
    if p.get("mergedAt"):
        try:
            mins = (parse(p["mergedAt"]) - parse(p["createdAt"])).total_seconds() / 60
            ttm.append((mins, p["number"], p["title"][:58]))
        except Exception:
            pass
ttm.sort()
buckets = {"<5min": 0, "5-15min": 0, "15-60min": 0, ">60min": 0}
for m, _, _ in ttm:
    buckets["<5min" if m < 5 else "5-15min" if m < 15 else "15-60min" if m < 60 else ">60min"] += 1
for k, v in buckets.items():
    print(f"  {k:>9}: {v:3d}  ({100*v//max(1,len(ttm))}%)")
print(f"\n  median: {ttm[len(ttm)//2][0]:.0f} min")
print("\n  FASTEST 15 (CI cannot finish in under ~5 min — integration alone takes 5m):")
for m, num, t in ttm[:15]:
    print(f"    {m:6.1f} min  #{num} {t}")

