import json, glob

S = "/private/tmp/claude-501/-Users-burakemre-Code-lobu/4226e7a7-3646-49f8-ac53-c326d3a23430/scratchpad"
REQ = {"typecheck", "format-lint", "migrations", "unit", "integration", "frontend", "pi-review"}

seen = {}
for f in glob.glob(S + "/p[123].json"):
    for p in json.load(open(f)):
        seen[p["number"]] = p


def rollup(p):
    st = {}
    for c in p.get("statusCheckRollup") or []:
        n = c.get("name") or c.get("context")
        if not n:
            continue
        s = c.get("conclusion") or c.get("state")
        if st.get(n) in ("FAILURE", "TIMED_OUT", "CANCELLED"):
            continue
        st[n] = s
    return st


groups = {
    "fix(...)  — bug fixes": lambda t: t.startswith("fix"),
    "feat(...) — features": lambda t: t.startswith("feat"),
    "chore/docs/refactor/test/style/ci": lambda t: not (t.startswith("fix") or t.startswith("feat")),
}

for label, pred in groups.items():
    sel = [p for p in seen.values() if pred(p["title"].lower())]
    clean = fail = miss = 0
    worst = []
    for p in sel:
        st = rollup(p)
        bad = [n for n, s in st.items() if s in ("FAILURE", "TIMED_OUT", "CANCELLED") and n in REQ]
        m = REQ - set(st)
        if bad:
            fail += 1
        if m:
            miss += 1
        if not bad and not m:
            clean += 1
        else:
            worst.append((p["number"], p["title"][:56], bad, sorted(m)))
    n = len(sel)
    print(f"\n=== {label}  (n={n}) ===")
    print(f"   all 7 required green at merge : {clean:3d}  ({100*clean//max(1,n)}%)")
    print(f"   >=1 required FAILING          : {fail:3d}  ({100*fail//max(1,n)}%)")
    print(f"   >=1 required NEVER REPORTED   : {miss:3d}  ({100*miss//max(1,n)}%)")
    print(f"   merged with gate not satisfied: {n-clean:3d}  ({100*(n-clean)//max(1,n)}%)")

