import json, os, glob, datetime, time

D = "/Users/burakemre/.claude/projects/-Users-burakemre-Code-lobu"
now = time.time()
ME = "4226e7a7"

rows = []
for f in glob.glob(os.path.join(D, "*.jsonl")):
    age = (now - os.path.getmtime(f)) / 60
    if age > 120:
        continue
    sid = os.path.basename(f)[:8]
    first_user, last_tools, last_ts = None, [], None
    try:
        with open(f, errors="replace") as fh:
            for line in fh:
                if '"type"' not in line:
                    continue
                try:
                    o = json.loads(line)
                except Exception:
                    continue
                t = o.get("type")
                if o.get("timestamp"):
                    last_ts = o["timestamp"]
                m = o.get("message") or {}
                c = m.get("content")
                if t == "user" and first_user is None:
                    if isinstance(c, list):
                        txt = " ".join(p.get("text", "") for p in c if isinstance(p, dict) and p.get("type") == "text")
                    elif isinstance(c, str):
                        txt = c
                    else:
                        txt = ""
                    txt = txt.strip()
                    if txt and not txt.startswith("<") and "Caveat:" not in txt[:60]:
                        first_user = txt.replace("\n", " ")[:220]
                if t == "assistant" and isinstance(c, list):
                    for p in c:
                        if isinstance(p, dict) and p.get("type") == "tool_use":
                            inp = json.dumps(p.get("input", {}))[:110]
                            last_tools.append(f"{p.get('name')} {inp}")
    except Exception:
        continue
    rows.append((age, sid, first_user, last_tools[-4:], last_ts))

rows.sort()
print(f"{len(rows)} sessions touched in the last 2h (mine = {ME})\n")
for age, sid, fu, lt, ts in rows:
    tag = "  <-- THIS SESSION" if sid == ME else ""
    print(f"--- {sid}  last write {age:5.1f} min ago{tag}")
    print(f"    TASK: {fu}")
    for x in lt:
        print(f"    ...  {x}")
    print()

