import { describe, expect, it } from "bun:test";
import { spawnSync } from "node:child_process";
import {
  chmodSync,
  mkdirSync,
  mkdtempSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { delimiter, join } from "node:path";
import { fileURLToPath } from "node:url";
// @ts-expect-error — plain .mjs script, no type declarations by design.
import {
  ancestorVerdict,
  CANONICAL_BASE,
  checkBaseBranch,
  classifyMergedPrs,
  STACKED_PR_LABEL,
} from "../check-merge-integrity.mjs";

const SCRIPT = fileURLToPath(
  new URL("../check-merge-integrity.mjs", import.meta.url)
);

/**
 * The first revision re-threw every non-1 exit status. In CI that crashed the
 * daily sweep instead of reporting a finding: #2273's merge commit exists only
 * on a deleted branch, so a fresh clone has no such object and `git merge-base
 * --is-ancestor` exits 128, not 1. It passed locally only because the
 * investigating clone had already fetched that object by hand.
 */
describe("ancestorVerdict", () => {
  it("reads exit 0 as reachable", () => {
    expect(ancestorVerdict({ status: 0, objectExists: true })).toBe(true);
  });

  it("reads exit 1 as not reachable — a normal answer", () => {
    expect(ancestorVerdict({ status: 1, objectExists: true })).toBe(false);
  });

  it("reads exit 128 on a MISSING object as not reachable — the #2273 shape", () => {
    expect(ancestorVerdict({ status: 128, objectExists: false })).toBe(false);
  });

  it("re-throws exit 128 when the object DOES exist — a real git failure", () => {
    // Must stay loud: a broken repo or bad ref must not read as "not on main".
    expect(ancestorVerdict({ status: 128, objectExists: true })).toBeNull();
  });

  it("re-throws an unrecognised status", () => {
    expect(ancestorVerdict({ status: 129, objectExists: false })).toBeNull();
    expect(
      ancestorVerdict({ status: Number.NaN, objectExists: false })
    ).toBeNull();
  });
});

function runReach(pr: {
  number: number;
  title: string;
  baseRefName: string;
  mergeCommit: { oid: string } | null;
  state: string;
}) {
  const root = mkdtempSync(join(tmpdir(), "merge-integrity-test-"));
  const bin = join(root, "bin");
  mkdirSync(bin);

  const git = join(bin, "git");
  writeFileSync(
    git,
    `#!/usr/bin/env node
const [command, flag, sha] = process.argv.slice(2);
if (command === "fetch") process.exit(0);
// "gone" reproduces a merge commit whose branch was deleted: git cannot
// resolve the object at all and exits 128, the way CI does on a fresh clone.
if (command === "cat-file" && flag === "-e") {
  process.exit(String(sha).startsWith("gone") ? 1 : 0);
}
if (command === "merge-base" && flag === "--is-ancestor") {
  if (String(sha).startsWith("gone")) process.exit(128);
  if (String(sha) === "brokenrepo") process.exit(128);
  process.exit(sha === "on-main" ? 0 : 1);
}
process.exit(2);
`
  );
  chmodSync(git, 0o755);

  const gh = join(bin, "gh");
  writeFileSync(
    gh,
    `#!/usr/bin/env node
process.stdout.write(process.env.FAKE_PR_JSON ?? "");
`
  );
  chmodSync(gh, 0o755);

  try {
    return spawnSync(
      process.execPath,
      [SCRIPT, "reach", "--pr", `${pr.number}`],
      {
        encoding: "utf8",
        env: {
          ...process.env,
          FAKE_PR_JSON: JSON.stringify(pr),
          PATH: `${bin}${delimiter}${process.env.PATH ?? ""}`,
        },
      }
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
}

