// Snapshot EVERY workspace manifest, read off disk — not the publish list.
//
// This used to restore only `__testing.PACKAGES`, the packages the release
// publishes. But the script under test is `bump-version.mjs`, which writes a
// different set: #2252 dropped plugin-api and plugin-host from the publish
// list because they ship inline, while bump-version still versions them. The
// two lists silently diverged, so every run of this suite left
// packages/plugin-api and packages/plugin-host rewritten to the fixture
// version `1.0.0-alpha.1+build.7` — a downgrade of two real manifests, on a
// green 27/27 suite. Any `git add -A` afterwards committed it.
//
// Deriving the snapshot from the filesystem cannot drift again: a package
// added to bump-version later is covered without touching this test.
const manifests = [
  join(REPO_ROOT, "package.json"),
  ...readdirSync(join(REPO_ROOT, "packages"), { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => join(REPO_ROOT, "packages", entry.name, "package.json"))
    .filter((file) => existsSync(file)),
];

